#!/bin/sh
# Provisions the SQS queues and the least-privilege IAM identities of the wallet
# stack. MiniStack runs this once it is ready, with its root credentials, and runs
# with AUTH=true so every later SQS call is checked against these IAM policies.
#
# Each identity's access key is generated by MiniStack and written as a profile
# to a shared AWS credentials file:
#   wallet-service  consumes wager-transactions.fifo, dead-letters permanent
#                   failures and publishes to wallet-events.fifo
#   wager-producer  may only send to wager-transactions.fifo (provider gateway)
#   events-reader   may only consume wallet-events.fifo (downstream consumer)
set -eu

CREDENTIALS_FILE="${WALLET_CREDENTIALS_FILE:-/shared/aws/credentials}"
REGION="${AWS_DEFAULT_REGION:-us-east-1}"
ENDPOINT="${AWS_ENDPOINT_URL:-http://localhost:4566}"

# The bundled aws CLI v1 ignores AWS_ENDPOINT_URL for SQS and would call real
# AWS, so every call names the MiniStack endpoint explicitly.
aws() { command aws --endpoint-url "$ENDPOINT" --region "$REGION" "$@"; }

INBOUND_QUEUE="wager-transactions.fifo"
DLQ_QUEUE="wager-transactions-dlq.fifo"
EVENTS_QUEUE="wallet-events.fifo"

VISIBILITY_TIMEOUT_SECONDS=30
MAX_RECEIVE_COUNT=5
INBOUND_RETENTION_SECONDS=345600 # 4 days
DLQ_RETENTION_SECONDS=1209600    # 14 days, the SQS maximum
EVENTS_RETENTION_SECONDS=1209600

ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
queue_arn() { echo "arn:aws:sqs:${REGION}:${ACCOUNT_ID}:$1"; }

aws sqs create-queue --queue-name "$DLQ_QUEUE" \
	--attributes "FifoQueue=true,MessageRetentionPeriod=${DLQ_RETENTION_SECONDS}" >/dev/null

cat >/tmp/inbound-attributes.json <<EOF
{
  "FifoQueue": "true",
  "VisibilityTimeout": "${VISIBILITY_TIMEOUT_SECONDS}",
  "ReceiveMessageWaitTimeSeconds": "20",
  "MessageRetentionPeriod": "${INBOUND_RETENTION_SECONDS}",
  "RedrivePolicy": "{\"deadLetterTargetArn\":\"$(queue_arn "$DLQ_QUEUE")\",\"maxReceiveCount\":\"${MAX_RECEIVE_COUNT}\"}"
}
EOF
aws sqs create-queue --queue-name "$INBOUND_QUEUE" \
	--attributes file:///tmp/inbound-attributes.json >/dev/null

aws sqs create-queue --queue-name "$EVENTS_QUEUE" \
	--attributes "FifoQueue=true,MessageRetentionPeriod=${EVENTS_RETENTION_SECONDS}" >/dev/null

# create_identity USER POLICY_JSON appends USER's new access key as a profile.
create_identity() {
	user="$1"
	policy="$2"
	if ! aws iam get-user --user-name "$user" >/dev/null 2>&1; then
		aws iam create-user --user-name "$user" >/dev/null
	fi
	aws iam put-user-policy --user-name "$user" --policy-name "${user}-sqs" \
		--policy-document "$policy"
	set -- $(aws iam create-access-key --user-name "$user" \
		--query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)
	printf '[%s]\naws_access_key_id = %s\naws_secret_access_key = %s\n\n' \
		"$user" "$1" "$2" >>"$CREDENTIALS_TMP"
}

mkdir -p "$(dirname "$CREDENTIALS_FILE")"
CREDENTIALS_TMP="${CREDENTIALS_FILE}.tmp"
: >"$CREDENTIALS_TMP"

create_identity wallet-service "$(cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ConsumeWagerTransactions",
      "Effect": "Allow",
      "Action": ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:ChangeMessageVisibility", "sqs:GetQueueUrl", "sqs:GetQueueAttributes"],
      "Resource": "$(queue_arn "$INBOUND_QUEUE")"
    },
    {
      "Sid": "DeadLetterPermanentFailures",
      "Effect": "Allow",
      "Action": ["sqs:SendMessage", "sqs:GetQueueUrl"],
      "Resource": "$(queue_arn "$DLQ_QUEUE")"
    },
    {
      "Sid": "PublishWalletEvents",
      "Effect": "Allow",
      "Action": ["sqs:SendMessage", "sqs:GetQueueUrl", "sqs:GetQueueAttributes"],
      "Resource": "$(queue_arn "$EVENTS_QUEUE")"
    }
  ]
}
EOF
)"

create_identity wager-producer "$(cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "SendWagerTransactions",
      "Effect": "Allow",
      "Action": ["sqs:SendMessage", "sqs:GetQueueUrl"],
      "Resource": "$(queue_arn "$INBOUND_QUEUE")"
    }
  ]
}
EOF
)"

create_identity events-reader "$(cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ConsumeWalletEvents",
      "Effect": "Allow",
      "Action": ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:ChangeMessageVisibility", "sqs:GetQueueUrl", "sqs:GetQueueAttributes"],
      "Resource": "$(queue_arn "$EVENTS_QUEUE")"
    }
  ]
}
EOF
)"

# Publish the credentials atomically so readers never see a partial file.
mv "$CREDENTIALS_TMP" "$CREDENTIALS_FILE"
chmod 0644 "$CREDENTIALS_FILE"
echo "provisioned queues and identities; credentials written to ${CREDENTIALS_FILE}"
